const int Count = sizeof(Glyphs) / sizeof(Glyphs[0]);

const Glyph *find(uint32_t codePoint)
{
    int low = 0;
    int high = Count - 1;
    while (low <= high) {
        const int middle = (low + high) / 2;
        if (Glyphs[middle].codePoint == codePoint) {
            return &Glyphs[middle];
        }
        if (Glyphs[middle].codePoint < codePoint) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }
    return nullptr;
}

